  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash|apply_patch|Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "KEEL_HOME={{KEEL_HOME}} KEEL_OVERLAY_DIR={{ROOT}}/overlay KEEL_DATA_DIR={{ROOT}}/data KEEL_CODEX_HOME='{{ROOT}}/custom codex' KEEL_AGENTS_HOME={{ROOT}}/.agents <runtime> {{KEEL_HOME}}/codex/hooks/pre-tool-use.ts",
            "timeout": 90
          }
        ]
      }
    ]
  }
}

